'use strict'

const { JSDOM } = require('jsdom')
const path = require('path')
const fs = require('fs')

// Create minimal DOM environment for tests
const dom = new JSDOM('<!doctype html><html><body></body></html>', {
  url: 'http://localhost',
  pretendToBeVisual: true,
})

// Essential globals
global.window = dom.window
global.document = dom.window.document
global.navigator = dom.window.navigator

// Core DOM elements needed for Vue
global.Element = dom.window.Element
global.HTMLElement = dom.window.HTMLElement
global.HTMLBodyElement = dom.window.HTMLBodyElement
global.SVGElement = dom.window.SVGElement || function SVGElement() {}
global.Node = dom.window.Node
global.Text = dom.window.Text

// Event types needed for tests
global.Event = dom.window.Event
global.MouseEvent = dom.window.MouseEvent

// Required browser APIs
global.requestAnimationFrame = (callback) => setTimeout(callback, 0)
global.cancelAnimationFrame = (id) => clearTimeout(id)
global.getComputedStyle = dom.window.getComputedStyle

// Load Vue
try {
  const vuePackagePath = require.resolve('vue/package.json')
  const vuePackage = require(vuePackagePath)
  const isVue2 = vuePackage.version && vuePackage.version.startsWith('2')

  let Vue
  if (isVue2) {
    const vuePath = path.dirname(vuePackagePath)
    const compilerPath = path.join(vuePath, 'dist/vue.js')
    Vue = fs.existsSync(compilerPath) ? require(compilerPath) : require('vue')
  } else {
    Vue = require('vue')
  }

  // Make Vue available globally and disable production tip
  global.Vue = Vue
  Vue.config && (Vue.config.productionTip = false)
} catch (e) {
  console.error('Error loading Vue:', e)
}
